import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { ChevronDown, ChevronUp, ExternalLink, Minus, Plus, RotateCcw } from 'lucide-react';
import './archive.css';

/**
 * 极简 PDF 阅读器：**pdf.js + 连续滚动 + 整份文档缩放**。
 *
 * 只做四件事，别的都不要：
 *   1. 逐页渲染到 canvas（只渲染视口附近的页，远的释放画布，56 页也不会吃爆内存）；
 *   2. 上下连续滚动（原生滚动、原生惯性）；
 *   3. 缩放：双指捏合 / 双击 / 工具栏 ± / Ctrl+滚轮，**整份文档一起缩放**，页面宽度与滚动高度随之变化；
 *   4. 翻页：上一页 / 下一页 / 页码输入 / 键盘。
 *
 * 刻意不做（做过，都删了）：标注、表单、签名、缩略图侧栏、目录、全文搜索、适配模式切换、旋转、
 * 每页单独缩放。展项上要的是"看清这份档案"，不是编辑器。
 *
 * 清晰度的取舍：画布按 `min(屏幕像素比 × 2, 2.5)` 倍的**上限**绘制一次，缩放只用 CSS 比例，
 * 所以捏合是即时的、不需要重绘，且放大 2 倍以内都是原生像素（按上限绘制 = 只会缩小、不会放大，
 * 不会出现"放大后是一张糊的点阵"）。代价是每页画布更大：A4 竖版在 DPR 2 下约 12 MB/页，
 * 因此只保留视口附近的几页。
 */

export interface PdfViewportLike {
  width: number;
  height: number;
}

export interface PdfPageLike {
  getViewport(options: { scale: number }): PdfViewportLike;
  render(options: { canvasContext: CanvasRenderingContext2D; viewport: PdfViewportLike }): { promise: Promise<unknown>; cancel?(): void };
}

export interface PdfDocumentLike {
  numPages: number;
  getPage(pageNumber: number): Promise<PdfPageLike>;
}

export type PdfLoader = (url: string) => Promise<PdfDocumentLike>;

const MIN_ZOOM = 0.5;
const MAX_ZOOM = 4;
const ZOOM_STEP = 0.25;
/** 画布倍率上限：只放大到这个倍率上，之后再放大就交给 CSS（再高内存翻倍、肉眼也看不出来）。 */
const MAX_RASTER = 2.5;
/** 只在视口上下各一屏内渲染。 */
const RENDER_MARGIN = '100% 0px';
/** 离当前页超过这么多页就释放画布。 */
const KEEP_DISTANCE = 3;
/** 尚未量到真实尺寸时的占位高宽比（A4 竖版）。 */
const PLACEHOLDER_RATIO = 842 / 595;
/** 阅读区左右内边距（.pdf-viewer-canvas 的 padding）。 */
const PADDING = 28;

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const clampZoom = (value: number) => clamp(Math.round(value * 100) / 100, MIN_ZOOM, MAX_ZOOM);

/** 站点内 pdf.js 附属数据的地址（跟随 BASE_URL，部署到子目录也有效）。 */
function pdfjsAssetUrl(dir: string): string {
  const base = import.meta.env.BASE_URL.endsWith('/') ? import.meta.env.BASE_URL : `${import.meta.env.BASE_URL}/`;
  return `${base}pdfjs/${dir}/`;
}

/**
 * 用 pdf.js 的 **legacy** 构建：modern 构建要求较新的运行时 API（`Promise.withResolvers`、
 * `Uint8Array.fromBase64`、`Float16Array` 等），老一点的手机内核会直接抛错；legacy 经过转译、
 * 自带 core-js，是官方给旧浏览器准备的产物（因此我们自己不需要再补 polyfill）。
 */
async function defaultLoadDocument(url: string): Promise<PdfDocumentLike> {
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  // 字面量必须是静态字符串，Vite 才能把 worker 作为资源打包（变量形式不会被打包）。
  pdfjs.GlobalWorkerOptions.workerSrc = new URL('pdfjs-dist/legacy/build/pdf.worker.min.mjs', import.meta.url).toString();
  return await pdfjs.getDocument({
    url,
    cMapUrl: pdfjsAssetUrl('cmaps'),
    cMapPacked: true,
    standardFontDataUrl: pdfjsAssetUrl('standard_fonts'),
  }).promise as unknown as PdfDocumentLike;
}

export function PdfViewer({ url, loadDocument = defaultLoadDocument }: { url: string; loadDocument?: PdfLoader }) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const pageNodes = useRef(new Map<number, HTMLDivElement>());
  const canvasNodes = useRef(new Map<number, HTMLCanvasElement>());
  /** 每页正在跑的渲染任务（用来取消）。 */
  const tasks = useRef(new Map<number, { promise: Promise<unknown>; cancel?(): void }>());
  /** 每页"收尾中"的承诺：同一张画布必须串行 render，取消也要等它结束。 */
  const inFlight = useRef(new Map<number, Promise<void>>());
  const painted = useRef(new Set<number>());
  const [pdfDocument, setPdfDocument] = useState<PdfDocumentLike | null>(null);
  const [pageCount, setPageCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(1);
  const [sizes, setSizes] = useState<Record<number, PdfViewportLike>>({});
  const [containerWidth, setContainerWidth] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  const [pageInput, setPageInput] = useState('1');
  const ratioRef = useRef(PLACEHOLDER_RATIO);
  const zoomRef = useRef(zoom);
  zoomRef.current = zoom;

  // ── 打开文档 ──────────────────────────────────────────────────────────
  useEffect(() => {
    let active = true;
    setPdfDocument(null);
    setPageCount(0);
    setError(null);
    setSizes({});
    setZoom(1);
    zoomRef.current = 1;
    painted.current.clear();
    tasks.current.forEach(task => task.cancel?.());
    tasks.current.clear();
    void loadDocument(url).then(value => {
      if (!active) return;
      setPdfDocument(value);
      setPageCount(value.numPages);
    }).catch(reason => {
      if (active) setError(reason instanceof Error ? reason.message : String(reason));
    });
    return () => { active = false; };
  }, [attempt, loadDocument, url]);

  // 离开页面时取消所有渲染，别让它在后台继续画。
  useEffect(() => () => {
    tasks.current.forEach(task => task.cancel?.());
    tasks.current.clear();
  }, []);

  /** 释放一页的画布。要等这一轮 render 真正结束再改尺寸，否则 pdf.js 会报"同一画布并发 render"。 */
  const releasePage = useCallback((pageNumber: number) => {
    const task = tasks.current.get(pageNumber);
    tasks.current.delete(pageNumber);
    painted.current.delete(pageNumber);
    task?.cancel?.();
    const settled = inFlight.current.get(pageNumber) ?? task?.promise.catch(() => {});
    const finish = () => {
      if (painted.current.has(pageNumber)) return;
      const canvas = canvasNodes.current.get(pageNumber);
      if (canvas) { canvas.width = 0; canvas.height = 0; }
    };
    if (settled) void settled.catch(() => {}).finally(finish);
    else finish();
  }, []);

  // ── 量阅读区宽度（"适配宽度"的基准） ─────────────────────────────────
  useEffect(() => {
    const box = scrollRef.current;
    if (!box) return;
    const measure = () => {
      const width = box.clientWidth;
      const changed = Math.abs(width - (scrollRef.current?.dataset.fitWidth ? Number(scrollRef.current.dataset.fitWidth) : 0)) > 1;
      if (scrollRef.current) scrollRef.current.dataset.fitWidth = String(width);
      if (changed && width > 0) for (const pageNumber of [...painted.current]) releasePage(pageNumber);
      setContainerWidth(width);
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    return () => observer.disconnect();
  }, [pdfDocument, releasePage]);

  // ── 渲染一页 ──────────────────────────────────────────────────────────
  const fitWidth = Math.max(120, (containerWidth || 595) - PADDING);
  const raster = clamp((typeof devicePixelRatio === 'number' ? devicePixelRatio : 1) * 2, 1, MAX_RASTER);

  const paintPage = useCallback(async (pageNumber: number) => {
    if (!pdfDocument || painted.current.has(pageNumber)) return;
    const canvas = canvasNodes.current.get(pageNumber);
    if (!canvas) return;
    const previous = inFlight.current.get(pageNumber);
    if (previous) await previous.catch(() => {});
    if (painted.current.has(pageNumber)) return;
    painted.current.add(pageNumber);
    try {
      const page = await pdfDocument.getPage(pageNumber);
      const natural = page.getViewport({ scale: 1 });
      const viewport = page.getViewport({ scale: (fitWidth / natural.width) * raster });
      ratioRef.current = viewport.height / Math.max(1, viewport.width);
      // 先落尺寸：占位块尽早换成真实高度，滚动位置与"第几页"才准。
      setSizes(previousSize => (previousSize[pageNumber] ? previousSize : { ...previousSize, [pageNumber]: viewport }));
      canvas.width = Math.max(1, Math.round(viewport.width));
      canvas.height = Math.max(1, Math.round(viewport.height));
      const context = canvas.getContext('2d');
      if (!context) throw new Error('浏览器无法创建画布');
      const task = page.render({ canvasContext: context, viewport });
      tasks.current.set(pageNumber, task);
      const holder: { settled?: Promise<void> } = {};
      const settled = task.promise.catch(() => {}).then(() => {
        if (tasks.current.get(pageNumber) === task) tasks.current.delete(pageNumber);
        if (holder.settled && inFlight.current.get(pageNumber) === holder.settled) inFlight.current.delete(pageNumber);
      });
      holder.settled = settled;
      inFlight.current.set(pageNumber, settled);
      await task.promise;
    } catch (reason) {
      painted.current.delete(pageNumber);
      tasks.current.delete(pageNumber);
      // 滚出视野/缩放导致的取消是正常路径，不上报。
      if ((reason as { name?: string } | null)?.name !== 'RenderingCancelledException') {
        setError(reason instanceof Error ? reason.message : String(reason));
      }
    }
  }, [fitWidth, pdfDocument, raster]);

  // 接近视口的页才渲染（没有 IntersectionObserver 的环境退化为只渲染当前页）。
  useEffect(() => {
    const root = scrollRef.current;
    if (!pdfDocument || !root || !containerWidth) return;
    if (typeof IntersectionObserver === 'undefined') {
      void paintPage(currentPage);
      return;
    }
    const observer = new IntersectionObserver(entries => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const pageNumber = Number((entry.target as HTMLElement).dataset.page);
        if (Number.isFinite(pageNumber)) void paintPage(pageNumber);
      }
    }, { root, rootMargin: RENDER_MARGIN });
    for (const node of pageNodes.current.values()) observer.observe(node);
    return () => observer.disconnect();
  }, [containerWidth, currentPage, pageCount, paintPage, pdfDocument]);

  // 滚动 → 当前页（取视口中心最近的一页）。
  useEffect(() => {
    const root = scrollRef.current;
    if (!root || !pageCount) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const center = root.scrollTop + root.clientHeight / 2;
      let best = 0;
      let bestDistance = Number.POSITIVE_INFINITY;
      for (const [pageNumber, node] of pageNodes.current) {
        if (node.offsetHeight === 0) continue;
        const distance = Math.abs(node.offsetTop + node.offsetHeight / 2 - center);
        if (distance < bestDistance) { bestDistance = distance; best = pageNumber; }
      }
      if (best) setCurrentPage(previous => (previous === best ? previous : best));
    };
    const onScroll = () => { if (!frame) frame = window.requestAnimationFrame(update); };
    root.addEventListener('scroll', onScroll, { passive: true });
    update();
    return () => {
      root.removeEventListener('scroll', onScroll);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [pageCount, sizes, zoom]);

  // 离当前页太远的页面释放画布。
  useEffect(() => {
    for (const pageNumber of [...painted.current]) {
      if (Math.abs(pageNumber - currentPage) > KEEP_DISTANCE) releasePage(pageNumber);
    }
  }, [currentPage, releasePage]);

  // ── 缩放：整份文档一起缩放，锚点内容停在原处 ──────────────────────────
  const applyZoom = useCallback((next: number, anchor?: { viewportY: number; contentY: number }) => {
    const root = scrollRef.current;
    const clamped = clampZoom(next);
    if (clamped === zoomRef.current) return;
    const ratio = clamped / zoomRef.current;
    const focus = anchor?.viewportY ?? (root ? root.clientHeight / 2 : 0);
    const contentPoint = anchor?.contentY ?? (root ? root.scrollTop + focus : 0);
    zoomRef.current = clamped;
    setZoom(clamped);
    if (!root) return;
    // 只重定位一次：分两次设 scrollTop 会"先跳一下再回位"。
    window.requestAnimationFrame(() => { root.scrollTop = Math.max(0, contentPoint * ratio - focus); });
  }, []);

  const zoomAtPointer = useCallback((factor: number, clientY: number) => {
    const root = scrollRef.current;
    const viewportY = clientY - (root?.getBoundingClientRect().top ?? 0);
    applyZoom(zoomRef.current * factor, { viewportY, contentY: (root?.scrollTop ?? 0) + viewportY });
  }, [applyZoom]);

  const goToPage = (pageNumber: number) => {
    if (!pageCount) return;
    const clamped = Math.min(Math.max(1, pageNumber), pageCount);
    setCurrentPage(clamped);
    setPageInput(String(clamped));
    void paintPage(clamped);
    const node = pageNodes.current.get(clamped);
    if (!node || typeof node.scrollIntoView !== 'function') return;
    try { node.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch { /* 旧环境忽略 */ }
    // 占位高度换成实测比例后位置会变，下一帧再补一枪。
    window.requestAnimationFrame(() => {
      const again = pageNodes.current.get(clamped);
      try { again?.scrollIntoView({ block: 'start' }); } catch { /* 忽略 */ }
    });
  };

  // ── 手势：双指捏合 = 整份文档缩放；单指交给浏览器原生滚动 ──────────────
  /** 按下的指针坐标（按 pointerId）：捏合要算两指间距与中点。 */
  const pointerPoints = useRef(new Map<number, { x: number; y: number }>());
  const pinch = useRef<{ startDistance: number; startZoom: number; viewportY: number; contentY: number } | null>(null);
  const lastTap = useRef(0);
  const tapStart = useRef<{ x: number; y: number } | null>(null);

  /**
   * 双指时禁掉浏览器自身的手势。`.pdf-viewer-canvas` 用 `touch-action: pan-y`（单指纵向滚动保留
   * 原生惯性），但这也允许**双指平移**——不拦的话"我在缩放、浏览器在滚动"，画面就是在滑动。
   * 只在双指时 preventDefault，单指滚动完全不受影响。
   */
  const bindTouchBlocker = useCallback((node: HTMLDivElement | null) => {
    if (!node) return;
    const onTouchMove = (event: TouchEvent) => {
      if (event.touches.length >= 2 && event.cancelable) event.preventDefault();
    };
    node.addEventListener('touchmove', onTouchMove, { passive: false });
    return () => node.removeEventListener('touchmove', onTouchMove);
  }, []);

  const onPointerDown = (event: React.PointerEvent) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    pointerPoints.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (pointerPoints.current.size === 2) {
      const root = scrollRef.current;
      const rect = root?.getBoundingClientRect();
      const [a, b] = [...pointerPoints.current.values()];
      if (!a || !b) return;
      const distance = Math.hypot(a.x - b.x, a.y - b.y) || 1;
      const viewportY = (a.y + b.y) / 2 - (rect?.top ?? 0);
      pinch.current = { startDistance: distance, startZoom: zoomRef.current, viewportY, contentY: (root?.scrollTop ?? 0) + viewportY };
      tapStart.current = null;
      return;
    }
    tapStart.current = { x: event.clientX, y: event.clientY };
  };

  const onPointerMove = (event: React.PointerEvent) => {
    if (!pointerPoints.current.has(event.pointerId)) return;
    pointerPoints.current.set(event.pointerId, { x: event.clientX, y: event.clientY });
    const gesture = pinch.current;
    if (!gesture || pointerPoints.current.size < 2) return;
    const [a, b] = [...pointerPoints.current.values()];
    if (!a || !b) return;
    const distance = Math.hypot(a.x - b.x, a.y - b.y) || 1;
    applyZoom(gesture.startZoom * (distance / gesture.startDistance), { viewportY: gesture.viewportY, contentY: gesture.contentY });
  };

  const onPointerUp = (event: React.PointerEvent) => {
    const wasDown = pointerPoints.current.delete(event.pointerId);
    if (pointerPoints.current.size < 2) pinch.current = null;
    const tap = tapStart.current;
    tapStart.current = null;
    if (!wasDown || pointerPoints.current.size > 0 || !tap) return;
    if (Math.hypot(event.clientX - tap.x, event.clientY - tap.y) >= 12) return;
    // 双击：不在放大态就放到 2 倍，已在放大态就还原。
    if (Date.now() - lastTap.current >= 300) { lastTap.current = Date.now(); return; }
    lastTap.current = 0;
    zoomAtPointer(zoomRef.current > 1.3 ? 1 / zoomRef.current : 2 / zoomRef.current, event.clientY);
  };

  const onWheel = (event: React.WheelEvent) => {
    // 触控板捏合 = ctrl/⌘ + wheel；普通滚轮留给页面滚动。
    if (!event.ctrlKey && !event.metaKey) return;
    event.preventDefault();
    zoomAtPointer(event.deltaY < 0 ? 1.1 : 1 / 1.1, event.clientY);
  };

  // 快捷键：翻页 / 缩放（正在输入页码时不抢键）。
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target && /^(input|textarea|select)$/i.test(target.tagName)) return;
      if (!pageCount) return;
      if (event.key === 'ArrowDown' || event.key === 'PageDown' || event.key === 'ArrowRight') { event.preventDefault(); goToPage(currentPage + 1); }
      else if (event.key === 'ArrowUp' || event.key === 'PageUp' || event.key === 'ArrowLeft') { event.preventDefault(); goToPage(currentPage - 1); }
      else if (event.key === 'Home') { event.preventDefault(); goToPage(1); }
      else if (event.key === 'End') { event.preventDefault(); goToPage(pageCount); }
      else if (event.key === '+' || event.key === '=') { event.preventDefault(); applyZoom(zoomRef.current + ZOOM_STEP); }
      else if (event.key === '-' || event.key === '_') { event.preventDefault(); applyZoom(zoomRef.current - ZOOM_STEP); }
      else if (event.key === '0') { event.preventDefault(); applyZoom(1); }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  });

  // 换文档时重置页码输入。
  useLayoutEffect(() => { setPageInput('1'); }, [url]);

  if (error) return (
    <div className="pdf-fallback" role="alert">
      <strong>PDF 无法预览</strong><span>{error}</span>
      <button type="button" onClick={() => setAttempt(value => value + 1)}>重试</button>
      <a href={url} target="_blank" rel="noreferrer">在新页面打开 <ExternalLink size={16} /></a>
    </div>
  );

  if (!pdfDocument) return <p className="viewer-loading">文档加载中</p>;

  const commitPageInput = () => {
    const value = Number(pageInput);
    if (Number.isFinite(value) && value >= 1) goToPage(Math.round(value));
    else setPageInput(String(currentPage));
  };

  return (
    <div className="pdf-viewer" tabIndex={0} aria-label="PDF 阅读器">
      <div
        className="pdf-viewer-canvas"
        ref={node => {
          scrollRef.current = node;
          return bindTouchBlocker(node);
        }}
        data-zoom={zoom}
        aria-label="PDF 文档，可上下滚动、双指缩放"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onWheel={onWheel}
      >
        <div className="pdf-viewer-pages">
          {Array.from({ length: pageCount }, (_, index) => index + 1).map(pageNumber => {
            const page = sizes[pageNumber];
            const width = page ? page.width / raster : fitWidth;
            const height = page ? page.height / raster : fitWidth * ratioRef.current;
            return (
              <div
                className="pdf-viewer-page"
                key={pageNumber}
                data-page={pageNumber}
                ref={node => { if (node) pageNodes.current.set(pageNumber, node); else pageNodes.current.delete(pageNumber); }}
                style={{ width: `${Math.round(width * zoom)}px`, height: `${Math.round(height * zoom)}px` }}
              >
                <canvas
                  ref={node => { if (node) canvasNodes.current.set(pageNumber, node); else canvasNodes.current.delete(pageNumber); }}
                  aria-label={`PDF 第 ${pageNumber} 页`}
                />
              </div>
            );
          })}
        </div>
      </div>

      <div className="pdf-viewer-bar">
        <button type="button" aria-label="上一页" disabled={currentPage <= 1} onClick={() => goToPage(currentPage - 1)}><ChevronUp /></button>
        <button type="button" aria-label="下一页" disabled={currentPage >= pageCount} onClick={() => goToPage(currentPage + 1)}><ChevronDown /></button>
        <label className="pdf-viewer-jump">
          <input
            type="number"
            min={1}
            max={pageCount}
            value={pageInput}
            aria-label="跳转到页"
            onChange={event => setPageInput(event.target.value)}
            onBlur={commitPageInput}
            onKeyDown={event => { if (event.key === 'Enter') commitPageInput(); }}
          />
          <span>/ {pageCount}</span>
        </label>
        <button type="button" aria-label="缩小" disabled={zoom <= MIN_ZOOM + 0.001} onClick={() => applyZoom(zoom - ZOOM_STEP)}><Minus /></button>
        <button type="button" aria-label="放大" disabled={zoom >= MAX_ZOOM - 0.001} onClick={() => applyZoom(zoom + ZOOM_STEP)}><Plus /></button>
        <button type="button" aria-label="复位缩放" disabled={zoom === 1} onClick={() => applyZoom(1)}><RotateCcw /></button>
        <a className="pdf-viewer-open" href={url} target="_blank" rel="noreferrer" aria-label="在新标签打开"><ExternalLink /></a>
      </div>
    </div>
  );
}

export default PdfViewer;
